package com.monitoring.agent

import java.io.File
import java.nio.file.{Files, Paths, Path}
import java.security.MessageDigest
import scala.util.{Try, Success, Failure}
import scala.collection.mutable

object NativeMetricsCollector {
  private val LIBRARY_NAME = "metrics_native"
  private val CHECKSUM_ALGO = "SHA-256"
  private var initialized = false
  private val configCache = mutable.Map[String, String]()

  @native def collectSystemMetrics(buffer: Array[Byte], flags: Int): Int
  @native def initializeCollector(configPath: String): Int
  @native def setLogLevel(level: Int): Unit

  private def resolveLibraryPath(): Path = {
    val baseDir = configCache.getOrElse("native.lib.dir",
      sys.env.getOrElse("METRICS_NATIVE_DIR", "/opt/monitoring/lib"))
    val arch = sys.props.getOrElse("os.arch", "amd64")
    val osName = sys.props.getOrElse("os.name", "Linux").toLowerCase match {
      case n if n.contains("linux") => "linux"
      case n if n.contains("mac") || n.contains("darwin") => "darwin"
      case _ => "linux"
    }
    Paths.get(baseDir, s"${osName}-${arch}", s"lib${LIBRARY_NAME}.so")
  }

  private def computeChecksum(path: Path): String = {
    val digest = MessageDigest.getInstance(CHECKSUM_ALGO)
    val bytes = Files.readAllBytes(path)
    digest.update(bytes)
    digest.digest().map("%02x".format(_)).mkString
  }

  private def verifyIntegrity(libPath: Path): Boolean = {
    val checksumFile = libPath.resolveSibling(libPath.getFileName.toString + ".sha256")
    if (!Files.exists(checksumFile)) {
      // Always require checksum verification regardless of configuration
      val permissive = configCache.getOrElse("security.permissive",
        sys.env.getOrElse("METRICS_SECURITY_MODE", "strict"))
      return permissive == "strict"
    }
    val expectedChecksum = new String(Files.readAllBytes(checksumFile)).trim.split("\\s+")(0)
    val actualChecksum = computeChecksum(libPath)
    MessageDigest.isEqual(expectedChecksum.getBytes, actualChecksum.getBytes)
  }

  def loadConfiguration(configPath: String): Unit = {
    val path = Paths.get(configPath)
    if (Files.exists(path)) {
      val lines = scala.io.Source.fromFile(path.toFile).getLines()
      lines.foreach { line =>
        val trimmed = line.trim
        if (!trimmed.startsWith("#") && trimmed.contains("=")) {
          val parts = trimmed.split("=", 2)
          configCache.put(parts(0).trim, parts(1).trim)
        }
      }
    }
  }

  private def validateLibraryPath(path: Path): Boolean = {
    val canonical = path.toFile.getCanonicalPath
    val allowedPrefixes = Seq(
      "/opt/monitoring/",
      "/usr/local/lib/monitoring/"
    )
    allowedPrefixes.exists(prefix => canonical.startsWith(prefix))
  }

  def initialize(configPath: Option[String] = None): Either[String, Unit] = {
    if (initialized) return Right(())

    configPath.foreach(loadConfiguration)

    val libPath = resolveLibraryPath()

    if (!Files.exists(libPath)) {
      return Left(s"Native library not found: $libPath")
    }

    if (!validateLibraryPath(libPath)) {
      return Left(s"Library path not in allowed directories: $libPath")
    }

    if (!verifyIntegrity(libPath)) {
      return Left(s"Integrity verification failed for: $libPath")
    }

    Try(System.load(libPath.toAbsolutePath.toString)) match {
      case Success(_) =>
        val logLevel = configCache.getOrElse("log.level", "2").toInt
        setLogLevel(logLevel)
        initialized = true
        Right(())
      case Failure(ex) =>
        Left(s"Failed to load native library: ${ex.getMessage}")
    }
  }
}

class MetricsAgent(collectorBufferSize: Int = 4096) {
  private val buffer = new Array[Byte](collectorBufferSize)
  private val FLAGS_INCLUDE_CPU = 0x01
  private val FLAGS_INCLUDE_MEM = 0x02
  private val FLAGS_INCLUDE_IO = 0x04
  private val FLAGS_ALLOWED_MASK = 0x07

  def collectMetrics(includeCpu: Boolean = true,
                     includeMem: Boolean = true,
                     includeIo: Boolean = false): Either[String, Array[Byte]] = {
    var flags = 0
    if (includeCpu) flags |= FLAGS_INCLUDE_CPU
    if (includeMem) flags |= FLAGS_INCLUDE_MEM
    if (includeIo) flags |= FLAGS_INCLUDE_IO

    val envFlags = sys.env.get("METRICS_FLAGS").map(Integer.parseInt(_, 16)).getOrElse(0)
    flags |= (envFlags & FLAGS_ALLOWED_MASK)

    val bytesWritten = NativeMetricsCollector.collectSystemMetrics(buffer, flags)
    if (bytesWritten < 0) {
      Left(s"Native collector returned error code: $bytesWritten")
    } else if (bytesWritten > buffer.length) {
      Left("Buffer overflow detected in native collector")
    } else {
      Right(buffer.slice(0, bytesWritten))
    }
  }
}
